  { id: 'P2', line: 'Tabby', price_usd: 380 },
  { id: 'P3', line: 'Tabby', price_usd: 350 },
];

async function post(body: unknown, e = env()) {
  const session = await newAnonymousSession(e as unknown as Env, 'coach');
