class BoundaryKV {
  data = new Map<string, string>();
  calls: string[] = [];
  failRead = false; failWrite = false;
  async get(key: string, type?: string) { this.calls.push(`get:${key}`); if (this.failRead) throw new Error('synthetic read failure'); const v = this.data.get(key); return v === undefined ? null : type === 'json' ? JSON.parse(v) : v; }
  async put(key: string, value: string) { this.calls.push(`put:${key}`); if (this.failWrite) throw new Error('synthetic write failure'); this.data.set(key, value); }
  async delete(key: string) { this.calls.push(`delete:${key}`); this.data.delete(key); }
  async list(o?: { prefix?: string }) { this.calls.push('list'); return { keys: [...this.data.keys()].filter(k => k.startsWith(o?.prefix ?? '')).map(name => ({ name })) }; }
}
function boundary(host = 'session') {
  const cache = new BoundaryKV(), sessions = new BoundaryKV(), effects: string[] = [];
  const pending: Promise<unknown>[] = [];
  const faults = { read: false, write: false };
  const objects = new Map<string, { shopper: ShopperReflex; data: Map<string, unknown> }>();
  const env = { CACHE: cache, SESSIONS: sessions, CONNECTOR_MODE: 'mock', DECISION_SOURCE: 'mock', REFLEX_HOST: host,
    JWT_SECRET: 'w0402-synthetic-signing-material-only', JWT_ISSUER: 'i', JWT_AUDIENCE: 'a', IDENTITY_SECRETS: 'meridian:backend-proof',
    TENANTS: JSON.stringify({ provisioned: ['coach', 'meridian'] }),
    PERSONALIZATION_WEBSOCKET: { idFromName: (n: string) => n, get: () => ({ fetch: async () => Response.json({ connections: 0 }) }) },
    DB: { prepare: () => { effects.push('capture'); return { bind: () => ({ run: async () => ({ success: true }) }) }; } },
  } as unknown as Env;
  const ns = {
    idFromName: (n: string) => n,
    get: (name: string) => ({ fetch: async (input: RequestInfo | URL, init?: RequestInit) => {
      effects.push(`object:${name}`);
      let item = objects.get(name);
      if (!item) {
        const data = new Map<string, unknown>();
        const storage = {
          get: async (k: string | string[]) => { if (faults.read) throw new Error('synthetic read failure'); return Array.isArray(k) ? new Map(k.map(v => [v, data.get(v)])) : data.get(k); },
          put: async (k: string | Record<string, unknown>, v?: unknown) => { effects.push(typeof k === 'string' ? `store:${k}` : 'store:behavior'); if (faults.write) throw new Error('synthetic write failure'); if (typeof k === 'string') data.set(k, structuredClone(v)); else for (const [key, value] of Object.entries(k)) data.set(key, structuredClone(value)); },
          deleteAll: async () => data.clear(), delete: async (k: string) => data.delete(k), setAlarm: async () => {}, getAlarm: async () => null,
        };
        item = { data, shopper: new ShopperReflex({ id: name, storage, getWebSockets: () => [], waitUntil: (p: Promise<unknown>) => pending.push(p) } as unknown as DurableObjectState, env) };
        objects.set(name, item);
      }
      return item.shopper.fetch(new Request(input, init));
    } }),
  };
  env.SHOPPER_REFLEX = ns as unknown as DurableObjectNamespace;
  const app = new Hono<{ Bindings: Env }>();
  app.use('*', tenantMiddleware()); app.route('/realtime', realtimeRoutes); app.route('/v1', identityRoutes); app.route('/v1', decisionRoutes); app.route('/sort', sortRoutes);
  const call = (path: string, capability?: string, body?: unknown, tenant = 'meridian', cookie?: string, geo?: { country: string; regionCode: string }) => {
    const request = new Request(`https://synthetic.invalid${path}`, {
    method: body === undefined ? 'GET' : 'POST', headers: { 'X-Tenant': tenant, ...(capability === undefined ? {} : { [SHOPPER_HEADER]: capability }), ...(cookie ? { Cookie: cookie } : {}), 'Content-Type': 'application/json' },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    if (geo) Object.defineProperty(request, 'cf', { value: geo });
    return app.request(request, undefined, env, { waitUntil: (p: Promise<unknown>) => pending.push(p), passThroughOnException() {}, props: {} });
  };
  const drain = async () => { while (pending.length) await Promise.all(pending.splice(0)); await new Promise(r => setTimeout(r, 10)); };
  return { env, cache, sessions, effects, objects, call, faults, drain };
}

